"""Statistics over the words of a text."""


def _extract_words(text):
    """Extract words from text, handling punctuation correctly.

    A word is a maximal run of letters and digits. An apostrophe between
    two alphanumeric characters is part of the word.
    """
    words = []
    current_word = []

    for i, char in enumerate(text):
        if char.isalnum():
            current_word.append(char)
        elif char == "'" and i > 0 and i < len(text) - 1 and text[i-1].isalnum() and text[i+1].isalnum():
            current_word.append(char)
        else:
            if current_word:
                words.append(''.join(current_word))
                current_word = []

    if current_word:
        words.append(''.join(current_word))

    return words


def average_word_length(text):
    words = _extract_words(text)
    if not words:
        return 0.0
    return sum(len(word) for word in words) / len(words)


def longest_word(text):
    best = ""
    for word in _extract_words(text):
        if len(word) > len(best):
            best = word
    return best


def word_frequencies(text):
    counts = {}
    for word in _extract_words(text.lower()):
        counts[word] = counts.get(word, 0) + 1
    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))
